def _horizontal_path(root_curve: dict) -> list:
    xs, ys = root_curve["tx_cm"], root_curve["ty_cm"]
    acc = [0.0]
    for i in range(1, len(xs)):
        acc.append(acc[-1] + math.hypot(xs[i] - xs[i - 1], ys[i] - ys[i - 1]))
